152→func droidStartupReadyPattern() string {
153→	return `(?s)(ENTER to send.*Current folder:|Current folder:.*ENTER to send)`
154→}
155→
156→func droidPromptReady(content string) bool {
157→	return strings.Contains(content, "ENTER to send") ||
158→		strings.Contains(content, "│ >") ||
159→		strings.Contains(content, "| >")
160→}
161→
162→func droidStartupMarkersReady(content string) bool {
163→	return strings.Contains(content, "ENTER to send") &&
164→		strings.Contains(content, "Current folder:")
165→}
