176→func (d *Droid) Bootstrap() error {
177→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
178→	if apiKey != "" {
179→		home, err := os.UserHomeDir()
180→		if err != nil {
181→			return fmt.Errorf("get home dir: %w", err)
182→		}
183→		dir := filepath.Join(home, ".factory")
184→		if err := os.MkdirAll(dir, 0o755); err != nil {
185→			return fmt.Errorf("mkdir %s: %w", dir, err)
186→		}
187→
188→		settingsPath := filepath.Join(dir, "settings.json")
189→
190→		// Read existing settings to merge (hooks may already be configured
191→		// in the repo-local .factory/settings.json, but the global config
192→		// at ~/.factory/settings.json might have other pre-existing entries).
193→		var settings droidSettings
194→		if data, readErr := os.ReadFile(settingsPath); readErr == nil {
195→			// Best-effort merge: ignore parse errors and start fresh
196→			_ = json.Unmarshal(data, &settings)
197→		}
198→
199→		// Replace or add the BYOK model entry.
200→		byokModel := droidCustomModel{
201→			DisplayName:    droidCustomModelDisplayName,
202→			Model:          droidCustomModelBaseID,
203→			BaseURL:        "https://api.anthropic.com",
204→			APIKey:         apiKey,
205→			Provider:       "anthropic",
206→			MaxOutputToken: 8192,
207→		}
208→
209→		found := false
210→		for i, m := range settings.CustomModels {
211→			if m.Model == byokModel.Model {
212→				settings.CustomModels[i] = byokModel
213→				found = true
214→				break
215→			}
216→		}
217→		if !found {
218→			settings.CustomModels = append(settings.CustomModels, byokModel)
219→		}
220→
221→		// Set the BYOK model as the default for interactive mode.
222→		if settings.SessionDefaultSettings == nil {
223→			settings.SessionDefaultSettings = &droidSessionDefaults{}
224→		}
225→		settings.SessionDefaultSettings.Model = droidCustomModelBaseID
226→
227→		data, err := json.MarshalIndent(settings, "", "  ")
228→		if err != nil {
229→			return fmt.Errorf("marshal settings: %w", err)
230→		}
231→		if err := os.WriteFile(settingsPath, data, 0o644); err != nil {
232→			return fmt.Errorf("write settings: %w", err)
233→		}
234→	}
235→
236→	cfg := droidStartupConfigFromEnv()
237→	if !cfg.warmup {
238→		return nil
239→	}
240→	if err := d.warmup(); err != nil {
241→		fmt.Fprintf(os.Stderr, "droid warmup failed (non-fatal): %v\n", err)
242→	}
243→	return nil
244→}
