293→func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
294→	_ = ctx
295→	cfg := droidStartupConfigFromEnv()
296→
297→	var s *TmuxSession
298→	var lastErr error
299→	handshakeRestartsLeft := cfg.handshakeRestarts
300→	for attempt := range cfg.attempts {
301→		name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
302→		var err error
303→		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", d.Binary())
304→		if err != nil {
305→			return nil, err
306→		}
307→
308→		// Resize so droid's full-screen TUI has room to render the prompt area.
309→		// The default 80x24 pane is too small — droid's splash + prompt needs ~30 lines.
310→		_ = exec.Command("tmux", "resize-window", "-t", name, "-x", "200", "-y", "50").Run()
311→
312→		// Phase 1: detect startup readiness (prompt OR known startup markers).
313→		if _, err := s.WaitFor(droidStartupReadyPattern(), cfg.timeout); err != nil {
314→			_ = s.Close()
315→			if attempt < cfg.attempts-1 {
316→				lastErr = err
317→				fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed during readiness wait: %s\n", attempt+1, cfg.attempts, err)
318→				time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
319→				continue
320→			}
321→			return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, err)
322→		}
323→
324→		// Phase 2: active handshake verifies the session can receive and answer prompts.
325→		handshakeOK := false
326→		for hAttempt := 1; hAttempt <= cfg.handshakeAttempts; hAttempt++ {
327→			token, err := d.performHandshake(s, cfg.handshakeTimeout)
328→			if err == nil {
329→				handshakeOK = true
330→				fmt.Fprintf(os.Stderr, "droid startup handshake succeeded on attempt %d/%d (token=%s)\n", hAttempt, cfg.handshakeAttempts, token)
331→				break
332→			}
333→			lastErr = err
334→			fmt.Fprintf(os.Stderr, "droid handshake attempt %d/%d failed: %v\n", hAttempt, cfg.handshakeAttempts, err)
335→		}
336→		if handshakeOK {
337→			s.stableAtSend = ""
338→			return s, nil
339→		}
340→
341→		content := s.Capture()
342→		_ = s.Close()
343→
344→		state := fmt.Sprintf("prompt=%t startup_markers=%t", droidPromptReady(content), droidStartupMarkersReady(content))
345→		wrappedErr := fmt.Errorf("startup handshake failed (%s): %w", state, lastErr)
346→		if handshakeRestartsLeft > 0 {
347→			handshakeRestartsLeft--
348→			lastErr = wrappedErr
349→			fmt.Fprintf(os.Stderr, "droid startup restarting session after handshake failure (%d restart(s) left): %v\n", handshakeRestartsLeft, wrappedErr)
350→			continue
351→		}
352→		if attempt < cfg.attempts-1 {
353→			lastErr = wrappedErr
354→			fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed after handshake retries: %v\n", attempt+1, cfg.attempts, wrappedErr)
355→			time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
356→			continue
357→		}
358→		return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, wrappedErr)
359→	}
360→	return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, lastErr)
361→}
362→
363→func (d *Droid) performHandshake(s *TmuxSession, timeout time.Duration) (string, error) {
364→	token := droidHandshakeToken()
365→	if err := s.Send(droidHandshakePrompt(token)); err != nil {
366→		return token, fmt.Errorf("send handshake prompt: %w", err)
367→	}
368→	if _, err := s.WaitFor(regexp.QuoteMeta(token), timeout); err != nil {
369→		return token, fmt.Errorf("wait for handshake token: %w", err)
370→	}
371→	// Token echo proves droid is responsive. The WaitFor settle mechanism
372→	// (content changed from pre-Send + stabilized) ensures the response is
373→	// complete. No additional prompt pattern wait needed.
374→	return token, nil
375→}
376→
377→func (d *Droid) warmup() error {
378→	const warmupAttempts = 2
379→	const warmupTimeout = 30 * time.Second
380→
381→	dir, err := os.MkdirTemp("", "droid-warmup-*")
382→	if err != nil {
383→		return fmt.Errorf("create warmup dir: %w", err)
384→	}
385→	defer func() { _ = os.RemoveAll(dir) }()
386→
387→	var lastErr error
388→	for attempt := range warmupAttempts {
389→		ctx, cancel := context.WithTimeout(context.Background(), warmupTimeout)
390→		out, err := d.RunPrompt(ctx, dir, "Reply with OK.", WithModel(defaultDroidModel))
391→		cancel()
392→		if err == nil {
393→			return nil
394→		}
395→
396→		lastErr = fmt.Errorf("%w (stderr: %s)", err, strings.TrimSpace(out.Stderr))
397→		if attempt < warmupAttempts-1 && d.IsTransientError(out, err) {
398→			time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
399→			continue
400→		}
401→		break
402→	}
403→	return lastErr
404→}
