 10→func TestDroidStartupReadyPattern(t *testing.T) {
 11→	t.Parallel()
 12→
 13→	re, err := regexp.Compile(droidStartupReadyPattern())
 14→	if err != nil {
 15→		t.Fatalf("compile pattern: %v", err)
 16→	}
 17→
 18→	tests := []struct {
 19→		name    string
 20→		content string
 21→		want    bool
 22→	}{
 23→		{
 24→			name: "startup markers",
 25→			content: `
 26→ENTER to send • \\ + ENTER for a new line • @ to mention files
 27→Current folder: /tmp/e2e-repo-123
 28→`,
 29→			want: true,
 30→		},
 31→		{
 32→			name: "startup markers reversed order",
 33→			content: `
 34→Current folder: /tmp/e2e-repo-123
