119→func configureDroidRepoSettings(repoDir string) error {
120→	home, err := os.UserHomeDir()
121→	if err != nil {
122→		return fmt.Errorf("get home dir: %w", err)
123→	}
124→
125→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
126→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
127→
128→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
129→		return err
130→	}
131→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
132→		return fmt.Errorf("exclude droid settings from git: %w", err)
133→	}
134→	return nil
135→}
