194→func ensureGitInfoExcludeContains(repoDir, entry string) error {
195→	excludePath := filepath.Join(repoDir, ".git", "info", "exclude")
196→
197→	data, err := os.ReadFile(excludePath)
198→	if err != nil && !errors.Is(err, os.ErrNotExist) {
199→		return fmt.Errorf("read %s: %w", excludePath, err)
200→	}
201→
202→	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
203→	for _, line := range strings.Split(normalized, "\n") {
204→		if strings.TrimSpace(line) == entry {
205→			return nil
206→		}
207→	}
208→
209→	var b strings.Builder
210→	if len(data) > 0 {
211→		b.Write(data)
212→		if data[len(data)-1] != '\n' {
213→			b.WriteByte('\n')
214→		}
215→	}
216→	b.WriteString(entry)
217→	b.WriteByte('\n')
218→
219→	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
220→		return fmt.Errorf("create %s: %w", filepath.Dir(excludePath), err)
221→	}
222→	if err := os.WriteFile(excludePath, []byte(b.String()), 0o644); err != nil {
223→		return fmt.Errorf("write %s: %w", excludePath, err)
224→	}
225→	return nil
226→}
