228→// ForEachAgent runs fn as a parallel subtest for every registered agent.
229→// It handles repo setup, concurrency gating, context timeout, and cleanup.
230→// The timeout is scaled by each agent's TimeoutMultiplier.
231→//
232→// If RunPrompt detects a transient API error (e.g. rate limit, token refresh
233→// failure), it panics with errScenarioRestart. ForEachAgent recovers from the
234→// panic and restarts the entire scenario with a fresh repository, up to
235→// maxScenarioRestarts times. This avoids stale CLI session state from the
236→// failed attempt poisoning the retry.
237→func ForEachAgent(t *testing.T, timeout time.Duration, fn func(t *testing.T, s *RepoState, ctx context.Context)) {
238→	t.Helper()
239→	t.Parallel()
240→	all := agents.All()
241→	if len(all) == 0 {
242→		t.Skip("no agents registered (check E2E_AGENT filter)")
243→	}
244→	for _, agent := range all {
245→		t.Run(agent.Name(), func(t *testing.T) {
246→			// Use the global test deadline for slot wait so we don't
247→			// skip prematurely — only bail if the whole binary is dying.
248→			slotCtx := context.Background()
249→			if deadline, ok := t.Deadline(); ok {
250→				var cancel context.CancelFunc
251→				slotCtx, cancel = context.WithDeadline(slotCtx, deadline)
252→				defer cancel()
253→			}
254→			if err := agents.AcquireSlot(slotCtx, agent); err != nil {
255→				t.Fatalf("timed out waiting for agent slot: %v", err)
256→			}
257→			defer agents.ReleaseSlot(agent)
258→
259→			// Per-test timeout starts after slot is acquired, scaled
260→			// by the agent's multiplier (e.g. 2.5× for gemini).
261→			scaled := time.Duration(float64(timeout) * agent.TimeoutMultiplier())
262→
263→			var prevState *RepoState
264→			for attempt := range maxScenarioRestarts + 1 {
265→				s := SetupRepo(t, agent)
266→				ctx, cancel := context.WithTimeout(context.Background(), scaled)
267→
268→				// On restart, suppress artifact capture from the previous
269→				// failed attempt so it doesn't overwrite the final one.
270→				if prevState != nil {
271→					prevState.skipArtifacts = true
272→				}
273→
274→				restarted := runScenario(t, s, ctx, fn)
275→				cancel()
276→
277→				if !restarted {
278→					return
279→				}
280→				prevState = s
281→				if attempt >= maxScenarioRestarts {
282→					t.Fatalf("exhausted %d scenario attempts due to transient API errors", maxScenarioRestarts+1)
283→				}
284→				t.Logf("transient error, restarting scenario (attempt %d/%d)", attempt+2, maxScenarioRestarts+1)
285→			}
286→		})
287→	}
288→}
289→
290→// runScenario runs the test function and recovers from errScenarioRestart
291→// panics triggered by transient API errors in RunPrompt. Returns true if
292→// the scenario should be restarted with a fresh repository.
293→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
294→	t.Helper()
295→	defer func() {
296→		if r := recover(); r != nil {
297→			if _, ok := r.(errScenarioRestart); ok {
298→				restarted = true
299→				return
300→			}
301→			panic(r) // re-panic for unexpected panics
302→		}
303→	}()
304→	fn(t, s, ctx)
305→	return false
306→}
307→
308→const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
309→
310→// errScenarioRestart is panicked by RunPrompt when a transient API error is
311→// detected. ForEachAgent recovers from this panic and restarts the test
312→// scenario with a fresh repository, avoiding stale CLI state from the failed
313→// attempt.
314→type errScenarioRestart struct {
315→	msg string
316→}
317→
318→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
319→// and returns the result. If the agent reports a transient API error, it
320→// panics with errScenarioRestart to trigger a full scenario restart in
321→// ForEachAgent (see runScenario).
322→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
323→	t.Helper()
324→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
325→	s.logPromptResult(out)
326→
327→	if err != nil && s.Agent.IsTransientError(out, err) {
328→		errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
329→		t.Logf("%s — restarting scenario", errMsg)
330→		fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
331→		panic(errScenarioRestart{msg: errMsg})
332→	}
333→
334→	return out, err
335→}
336→
337→func (s *RepoState) logPromptResult(out agents.Output) {
338→	s.ConsoleLog.WriteString("> " + out.Command + "\n")
339→	s.ConsoleLog.WriteString("stdout:\n" + out.Stdout + "\n")
340→	s.ConsoleLog.WriteString("stderr:\n" + out.Stderr + "\n")
341→}
