390→func (s *RepoState) shouldUseDroidHandshakeRecovery(pattern string) bool {
391→	return s.Agent.Name() == "factoryai-droid" &&
392→		pattern == s.Agent.PromptPattern()
393→}
394→
395→func (s *RepoState) recoverDroidPromptTimeoutWithHandshake(session agents.Session, _ string, timeout time.Duration) (string, error) {
396→	token := fmt.Sprintf("ENTIRE_E2E_READY_%d", time.Now().UnixNano())
397→	handshakePrompt := "E2E transport check. Reply with exactly this token and nothing else: " + token +
398→		". Do not edit files, run commands, or commit."
399→
400→	fmt.Fprintf(s.ConsoleLog, "> [recovery] send handshake prompt with token %s\n", token)
401→	if err := session.Send(handshakePrompt); err != nil {
402→		return "", fmt.Errorf("send handshake prompt: %w", err)
403→	}
404→
405→	content, err := session.WaitFor(regexp.QuoteMeta(token), timeout)
406→	fmt.Fprintf(s.ConsoleLog, "> pane after handshake token wait:\n%s\n", content)
407→	if err != nil {
408→		return content, fmt.Errorf("wait for handshake token: %w", err)
409→	}
410→
411→	// Token echo proves the session is responsive. The WaitFor settle
412→	// mechanism ensures the response has stabilized. No additional prompt
413→	// pattern wait needed — it was the source of CI flakiness.
414→	return content, nil
415→}
