func droidStartupConfigFromEnv() droidStartupConfig {
	cfg := droidStartupConfig{
		attempts:          2,
		timeout:           60 * time.Second,
		warmup:            false,
		handshakeTimeout:  45 * time.Second,
		handshakeAttempts: 2,
