func droidHandshakeToken() string {
	return fmt.Sprintf("ENTIRE_E2E_READY_%d", time.Now().UnixNano())
}

func droidHandshakePrompt(token string) string {
	return "E2E handshake check. Reply with exactly this token and nothing else: " + token +
		". Do not edit files, run commands, or commit."
}

func (d *Droid) Bootstrap() error {

func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
	_ = ctx
	cfg := droidStartupConfigFromEnv()

	var s *TmuxSession
	var lastErr error
	handshakeRestartsLeft := cfg.handshakeRestarts
	for attempt := range cfg.attempts {
		name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
		var err error
		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", d.Binary())
		if err != nil {
			return nil, err
		}

		// Resize so droid's full-screen TUI has room to render the prompt area.
		// The default 80x24 pane is too small — droid's splash + prompt needs ~30 lines.
		_ = exec.Command("tmux", "resize-window", "-t", name, "-x", "200", "-y", "50").Run()

		// Phase 1: detect startup readiness (prompt OR known startup markers).
		if _, err := s.WaitFor(droidStartupReadyPattern(), cfg.timeout); err != nil {
			_ = s.Close()
			if attempt < cfg.attempts-1 {
				lastErr = err
				fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed during readiness wait: %s\n", attempt+1, cfg.attempts, err)
				time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
				continue
			}
			return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, err)
		}

		// Phase 2: active handshake verifies the session can receive and answer prompts.
		handshakeOK := false
		for hAttempt := 1; hAttempt <= cfg.handshakeAttempts; hAttempt++ {
			token, err := d.performHandshake(s, cfg.handshakeTimeout)
			if err == nil {
				handshakeOK = true
				fmt.Fprintf(os.Stderr, "droid startup handshake succeeded on attempt %d/%d (token=%s)\n", hAttempt, cfg.handshakeAttempts, token)
				break
			}
			lastErr = err
			fmt.Fprintf(os.Stderr, "droid handshake attempt %d/%d failed: %v\n", hAttempt, cfg.handshakeAttempts, err)
		}
		if handshakeOK {
			s.stableAtSend = ""
			return s, nil
		}

		content := s.Capture()
		_ = s.Close()

		state := fmt.Sprintf("prompt=%t startup_markers=%t", droidPromptReady(content), droidStartupMarkersReady(content))
		wrappedErr := fmt.Errorf("startup handshake failed (%s): %w", state, lastErr)
		if handshakeRestartsLeft > 0 {
			handshakeRestartsLeft--
			lastErr = wrappedErr
			fmt.Fprintf(os.Stderr, "droid startup restarting session after handshake failure (%d restart(s) left): %v\n", handshakeRestartsLeft, wrappedErr)
			continue
		}
		if attempt < cfg.attempts-1 {
			lastErr = wrappedErr
			fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed after handshake retries: %v\n", attempt+1, cfg.attempts, wrappedErr)
			time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
			continue
		}
		return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, wrappedErr)
	}
	return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, lastErr)
}

func (d *Droid) performHandshake(s *TmuxSession, timeout time.Duration) (string, error) {
	token := droidHandshakeToken()
	if err := s.Send(droidHandshakePrompt(token)); err != nil {
		return token, fmt.Errorf("send handshake prompt: %w", err)
	}
	if _, err := s.WaitFor(regexp.QuoteMeta(token), timeout); err != nil {
		return token, fmt.Errorf("wait for handshake token: %w", err)
	}
	// Token echo proves droid is responsive. The WaitFor settle mechanism
	// (content changed from pre-Send + stabilized) ensures the response is
	// complete. No additional prompt pattern wait needed.
	return token, nil
}

